import { test, expect } from '@playwright/test';

test.describe('Table Column Freezing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should freeze the first column when scrolling horizontally', async ({ page }) => {
    const table = page.getByRole('table');
    const firstColumn = table.locator('tr td:first-child');

    await expect(firstColumn).toBeVisible();

    await page.evaluate(() => {
      window.scrollBy(500, 0); // Simulate horizontal scroll
    });

    await expect(firstColumn).toBeVisible(); // First column should still be visible
  });

  test('should allow scrolling without affecting the first column', async ({ page }) => {
    const firstColumn = page.getByRole('columnheader', { name: 'First Column' }); // Adjust based on actual header name

    await page.evaluate(() => {
      window.scrollBy(500, 0); // Simulate horizontal scroll
    });

    await expect(firstColumn).toBeVisible(); // First column header should still be visible
  });
});
